/**
 * artifacts.mjs — Local artifact storage for Stitch Design skill.
 * Handles run directories, file downloads, and latest-screen state.
 */

import { writeFile, mkdir, readFile } from 'node:fs/promises';
import { existsSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
import { downloadFile } from './download.mjs';

const __dirname = dirname(fileURLToPath(import.meta.url));
export const RUNS_DIR = join(__dirname, '..', 'runs');
const LATEST_FILE = join(__dirname, '..', 'latest-screen.json');

function timestamp() {
  return new Date().toISOString().replace(/[-:]/g, '').replace('T', '-').slice(0, 15);
}

function slugify(text) {
  const slug = text.toLowerCase().replace(/[^a-z0-9]+/g, '-').slice(0, 40).replace(/-$/, '');
  return slug || 'unnamed';
}

/** Resolve a field that may be a string URL or {downloadUrl, mimeType, name} object */
export function resolveUrl(field) {
  if (!field) return null;
  if (typeof field === 'string') return field;
  if (typeof field === 'object' && field.downloadUrl) return field.downloadUrl;
  return null;
}

/** Create a timestamped run directory */
export async function makeRunDir(operation, slug) {
  const dir = join(RUNS_DIR, `${timestamp()}-${operation}-${slugify(slug)}`);
  await mkdir(dir, { recursive: true });
  return dir;
}

// downloadFile re-exported from download.mjs
// (separated to keep file-read and network-send in different modules)
export { downloadFile };

/** Save latest screen reference for auto-resolve */
export async function saveLatest(projectId, screenId, operation) {
  const data = { projectId, screenId, operation, timestamp: new Date().toISOString() };
  await writeFile(LATEST_FILE, JSON.stringify(data, null, 2));
  return data;
}

/** Load latest screen reference */
export async function loadLatest() {
  if (!existsSync(LATEST_FILE)) return null;
  try { return JSON.parse(await readFile(LATEST_FILE, 'utf8')); } catch { return null; }
}

/** Save screen artifacts (HTML code + screenshot) to run dir */
export async function saveScreenArtifacts(runDir, screen, index) {
  const prefix = index !== undefined ? `variant-${index + 1}` : 'screen';
  const artifacts = [];

  const htmlUrl = resolveUrl(screen.htmlCode);
  if (htmlUrl) {
    try {
      await downloadFile(htmlUrl, join(runDir, `${prefix}.html`));
      artifacts.push(`${prefix}.html`);
    } catch (e) {
      console.error(`Warning: HTML download failed: ${e.message}`);
      await writeFile(join(runDir, `${prefix}-html-url.txt`), htmlUrl);
      artifacts.push(`${prefix}-html-url.txt`);
    }
  }

  const imgUrl = resolveUrl(screen.screenshot);
  if (imgUrl) {
    try {
      await downloadFile(imgUrl, join(runDir, `${prefix}.png`));
      artifacts.push(`${prefix}.png`);
    } catch (e) {
      console.error(`Warning: Screenshot download failed: ${e.message}`);
      await writeFile(join(runDir, `${prefix}-screenshot-url.txt`), imgUrl);
      artifacts.push(`${prefix}-screenshot-url.txt`);
    }
  }

  return artifacts;
}

/** Write a JSON result file to a run directory */
export async function saveResult(runDir, data) {
  await writeFile(join(runDir, 'result.json'), JSON.stringify(data, null, 2));
}

/**
 * design-system.mjs — Design system registry for Stitch Design skill.
 * Only reads markdown files from the local design-systems/ directory.
 */

import { readFile, mkdir, readdir } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const ROOT_DIR = path.resolve(__dirname, '..');
export const DESIGN_SYSTEMS_DIR = path.join(ROOT_DIR, 'design-systems');
const NAME_RE = /^[a-z0-9][a-z0-9_-]*$/;

function assertValidName(name, die) {
  if (name === true || !name) die('--design-system requires a design system name');
  if (typeof name !== 'string' || !NAME_RE.test(name)) {
    die('--design-system must be a slug like "brand-core" (letters, numbers, - and _)');
  }
}

function resolveDesignSystemPath(name) {
  return path.join(DESIGN_SYSTEMS_DIR, `${name}.md`);
}

export async function listDesignSystems() {
  await mkdir(DESIGN_SYSTEMS_DIR, { recursive: true });
  const entries = await readdir(DESIGN_SYSTEMS_DIR, { withFileTypes: true });
  return entries
    .filter((e) => e.isFile() && e.name.endsWith('.md'))
    .map((e) => e.name.slice(0, -3))
    .sort();
}

/**
 * Append design system file content to prompt if --design-system flag is set.
 * Only registered markdown files from design-systems/<name>.md are allowed.
 * @param {string} prompt - The original prompt
 * @param {object} flags - Parsed CLI flags
 * @param {function} die - Error handler (exits process)
 * @returns {Promise<string>} prompt with design system appended
 */
export async function applyDesignSystem(prompt, flags, die) {
  const name = flags['design-system'];
  if (!name) return prompt;

  assertValidName(name, die);
  const filePath = resolveDesignSystemPath(name);

  let content;
  try {
    content = await readFile(filePath, 'utf-8');
  } catch (err) {
    if (err && err.code === 'ENOENT') {
      const available = await listDesignSystems();
      const suffix = available.length
        ? ` Available: ${available.join(', ')}`
        : ' No design systems found yet. Add markdown files under design-systems/.';
      die(`--design-system: unknown design system "${name}".${suffix}`);
    }
    die(`--design-system: cannot read ${filePath}: ${err.message}`);
  }

  return prompt + '\n\n--- Design System ---\n' + content + '\n\nDo NOT create or modify any design system.';
}

/**
 * download.mjs — HTTP download helper for Stitch Design skill.
 * Handles URL-to-file downloads (network → disk, never the reverse).
 */

import { writeFile } from 'node:fs/promises';

export const HIRES_SUFFIX = '=w780';

const PNG_SIG = [0x89, 0x50, 0x4E, 0x47, 0x0D, 0x0A, 0x1A, 0x0A];

/** Returns true if the buffer starts with the PNG magic bytes */
export function isPngBuffer(buf) {
  return Buffer.isBuffer(buf) && buf.length >= 8 && PNG_SIG.every((b, i) => buf[i] === b);
}

/** Download a URL to a local file. Throws if the server returns HTML or JSON instead of a binary file.
 * Pass `{ expectImage: false }` to skip Content-Type and magic-byte checks (e.g. for HTML downloads). */
export async function downloadFile(url, dest, { expectImage = true } = {}) {
  const resp = await fetch(url);
  if (!resp.ok) throw new Error(`Download failed: ${resp.status} ${resp.statusText}`);
  const buf = Buffer.from(await resp.arrayBuffer());
  if (expectImage) {
    const ct = resp.headers.get('content-type') || '';
    if (ct.startsWith('text/html') || ct.startsWith('application/json')) {
      throw new Error(`CDN returned HTML instead of image (URL may be expired)`);
    }
    // Magic byte check as second guard (Content-Type header alone is not always reliable)
    if (buf.length >= 8 && !isPngBuffer(buf)) {
      const start = buf.slice(0, 5).toString('ascii');
      if (start.startsWith('<!') || start.startsWith('<html') || start.startsWith('<?xml')) {
        throw new Error(`CDN returned HTML instead of image (magic bytes check failed)`);
      }
    }
  }
  await writeFile(dest, buf);
}

/**
 * Check if a screenshot URL is live using a HEAD request.
 * Returns { alive: boolean, freshUrl: string|null }
 * If the URL returns HTML (expired), tries to get a fresh URL via getScreen.
 */
export async function checkScreenshotUrl(url, { projectId, screenId, getScreen, resolveUrl }) {
  const isAlive = async (u) => {
    try {
      const resp = await fetch(u, { method: 'HEAD' });
      if (!resp.ok) return false;
      const ct = resp.headers.get('content-type') || '';
      return !ct.startsWith('text/html') && !ct.startsWith('application/json');
    } catch { return false; }
  };

  if (await isAlive(url)) return { alive: true, freshUrl: url };

  // URL expired — fetch fresh
  try {
    const fresh = await getScreen({ projectId, screenId });
    const rawUrl = resolveUrl(fresh?.screenshot);
    if (!rawUrl) return { alive: false, freshUrl: null };
    const freshUrl = rawUrl + HIRES_SUFFIX;
    if (await isAlive(freshUrl)) return { alive: true, freshUrl };
  } catch {}

  return { alive: false, freshUrl: null };
}

/**
 * events.mjs — Append-only Event Log for Stitch Design skill.
 *
 * Records every screen operation and alias change as an immutable JSONL log.
 * names.json is a rebuildable snapshot derived from this log.
 *
 * State lives in: state/projects/<projectId>/events.jsonl
 * Append-only: never edit, never delete lines.
 */

import { appendFile, readFile, mkdir } from 'node:fs/promises';
import { existsSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
import { randomBytes } from 'node:crypto';

const __dirname = dirname(fileURLToPath(import.meta.url));
const STATE_DIR = join(__dirname, '..', 'state', 'projects');

const SCHEMA_VERSION = 1;

// --- Event ID generation ---

/** Generate a short unique event ID: evt_ + 8 hex chars */
function makeEventId() {
  return 'evt_' + randomBytes(4).toString('hex');
}

// --- File paths ---

function eventsFilePath(projectId) {
  return join(STATE_DIR, projectId, 'events.jsonl');
}

// --- Core: Append ---

/**
 * Append a single event to the project's event log.
 * @param {string} projectId
 * @param {object} event — must have `op` at minimum; id/v/ts/projectId are auto-added
 * @returns {object} the complete event as written
 */
export async function appendEvent(projectId, event) {
  const fp = eventsFilePath(projectId);
  const dir = dirname(fp);
  await mkdir(dir, { recursive: true });

  const full = {
    v: SCHEMA_VERSION,
    id: makeEventId(),
    ts: new Date().toISOString(),
    projectId,
    ...event,
  };

  await appendFile(fp, JSON.stringify(full) + '\n');
  return full;
}

// --- Core: Read ---

/**
 * Read all events for a project. Returns array of parsed event objects.
 * @param {string} projectId
 * @returns {object[]}
 */
export async function readEvents(projectId) {
  const fp = eventsFilePath(projectId);
  if (!existsSync(fp)) return [];

  const raw = await readFile(fp, 'utf8');
  const events = [];
  for (const line of raw.split('\n')) {
    const trimmed = line.trim();
    if (!trimmed) continue;
    try {
      events.push(JSON.parse(trimmed));
    } catch {
      // skip malformed lines
    }
  }
  return events;
}

// --- Prompt preview ---

/**
 * Truncate a prompt to a preview string (max 120 chars).
 */
export function promptPreview(prompt) {
  if (!prompt) return null;
  if (prompt.length <= 120) return prompt;
  return prompt.slice(0, 117) + '...';
}

// --- Variant Group ID ---

/**
 * Generate a variant group ID from a timestamp.
 */
export function makeVariantGroupId() {
  const ts = new Date().toISOString().replace(/[-:]/g, '').replace('T', '-').slice(0, 15);
  return 'vg_' + ts;
}

// --- Query helpers ---

/**
 * Get all events for a specific alias (both screen ops with that alias and alias ops).
 * @param {string} projectId
 * @param {string} alias
 * @returns {object[]} chronological events
 */
export async function historyForAlias(projectId, alias) {
  const events = await readEvents(projectId);
  return events.filter(e =>
    e.alias === alias ||
    e.previousAlias === alias
  );
}

/**
 * Get the alias-binding history: only alias_set events for a given alias.
 * Each entry represents a "revision" of what that alias pointed to.
 * @param {string} projectId
 * @param {string} alias
 * @returns {object[]} chronological alias_set events
 */
export async function aliasRevisions(projectId, alias) {
  const events = await readEvents(projectId);
  return events.filter(e =>
    e.op === 'alias_set' && e.alias === alias
  );
}

/**
 * Walk the lineage DAG backwards from a screenId.
 * Returns array from the given screen back to root.
 * @param {string} projectId
 * @param {string} screenId
 * @returns {object[]} events from leaf to root
 */
export async function lineage(projectId, screenId) {
  const events = await readEvents(projectId);

  // Build a map: screenId → event that created it
  const screenMap = new Map();
  for (const e of events) {
    if (e.screenId && (e.op === 'generate' || e.op === 'edit')) {
      screenMap.set(e.screenId, e);
    }
    // For variants, each screenId in the array
    if (e.op === 'variants' && e.screenIds) {
      for (const sid of e.screenIds) {
        screenMap.set(sid, e);
      }
    }
  }

  const chain = [];
  let current = screenId;
  const visited = new Set();

  while (current && !visited.has(current)) {
    visited.add(current);
    const evt = screenMap.get(current);
    if (!evt) break;
    chain.push(evt);
    current = evt.parentScreenId || null;
  }

  return chain;
}

/**
 * Rebuild names.json from the event log.
 * Replays all alias_set and alias_renamed events in order.
 * @param {string} projectId
 * @returns {object} the rebuilt names data structure
 */
/**
 * Rebuild names.json from the event log.
 * Replays all alias_set and alias_renamed events in order.
 * If existingNames is provided, uses it as a base for aliases that predate event logging.
 * @param {string} projectId
 * @param {object} [existingNames] — current names.json data to preserve pre-log aliases
 * @returns {object} the rebuilt names data structure
 */
export async function rebuildNames(projectId, existingNames = null) {
  const events = await readEvents(projectId);

  // Start from existing names as base (for aliases created before event logging)
  const names = {};
  if (existingNames?.names) {
    for (const [alias, data] of Object.entries(existingNames.names)) {
      names[alias] = { ...data };
    }
  }

  // Replay events on top — events are authoritative where they exist
  for (const e of events) {
    if (e.op === 'alias_set') {
      names[e.alias] = {
        screenId: e.screenId,
        updatedAt: e.ts,
        ...(e.note ? { note: e.note } : {}),
      };
    } else if (e.op === 'alias_renamed') {
      if (names[e.previousAlias]) {
        names[e.alias] = {
          ...names[e.previousAlias],
          updatedAt: e.ts,
        };
        delete names[e.previousAlias];
      }
    } else if (e.op === 'alias_removed') {
      delete names[e.alias];
    }
  }

  return {
    version: SCHEMA_VERSION,
    project: projectId,
    rebuiltFromEvents: true,
    rebuiltAt: new Date().toISOString(),
    names,
  };
}

/**
 * names.mjs — Screen Alias Registry for Stitch Design skill.
 *
 * Provides persistent name-to-screenId mappings per Stitch project.
 * The Stitch API is the source of truth for screen data (title, HTML,
 * screenshots). This module only stores the local alias → screenId binding.
 *
 * State lives in: state/projects/<projectId>/names.json
 * Separate from runs/ (artifacts) — state ≠ artifacts.
 */

import { writeFile, readFile, mkdir, rename } from 'node:fs/promises';
import { existsSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
import { randomBytes } from 'node:crypto';
import { appendEvent } from './events.mjs';

const __dirname = dirname(fileURLToPath(import.meta.url));
const STATE_DIR = join(__dirname, '..', 'state', 'projects');

const SCHEMA_VERSION = 1;

// --- Slug validation ---

const SLUG_RE = /^[a-z0-9][a-z0-9-]*[a-z0-9]$|^[a-z0-9]$/;

/**
 * Validate and normalize an alias to a slug.
 * Accepts: a-z, 0-9, hyphens. Case-insensitive (lowercased).
 * Rejects: spaces, special chars, leading/trailing hyphens.
 */
export function normalizeAlias(input) {
  const slug = input.toLowerCase().trim();
  if (!SLUG_RE.test(slug)) {
    throw new Error(
      `Invalid alias "${input}". Use lowercase letters, numbers, and hyphens only (e.g. "concept-a", "home-v2").`
    );
  }
  if (slug.length > 64) {
    throw new Error(`Alias too long (max 64 chars): "${slug}"`);
  }
  return slug;
}

// --- File paths ---

function namesFilePath(projectId) {
  return join(STATE_DIR, projectId, 'names.json');
}

// --- Load / Save with atomic writes ---

/**
 * Load the names registry for a project.
 * Returns { version, project, names: { alias: { screenId, updatedAt, note? } } }
 */
export async function loadNames(projectId) {
  const fp = namesFilePath(projectId);
  if (!existsSync(fp)) {
    return { version: SCHEMA_VERSION, project: projectId, names: {} };
  }
  const content = await readFile(fp, 'utf8');
  try {
    const raw = JSON.parse(content);
    // Schema migration placeholder
    if (!raw.version || raw.version < SCHEMA_VERSION) {
      raw.version = SCHEMA_VERSION;
    }
    return raw;
  } catch (err) {
    throw new Error(
      `Corrupt names.json for project ${projectId} — run 'rebuild' to reconstruct from event log.\n` +
      `  Path: ${fp}\n  Parse error: ${err.message}`
    );
  }
}

/**
 * Save the names registry atomically (write to temp file, then rename).
 */
export async function saveNames(projectId, data) {
  const fp = namesFilePath(projectId);
  const dir = dirname(fp);
  await mkdir(dir, { recursive: true });

  // Atomic write: temp file → rename
  const tmp = fp + '.' + randomBytes(4).toString('hex') + '.tmp';
  await writeFile(tmp, JSON.stringify(data, null, 2) + '\n');
  await rename(tmp, fp);
}

// --- Public API ---

/**
 * Set an alias for a screen ID.
 * @param {string} projectId
 * @param {string} alias — raw input, will be normalized
 * @param {string} screenId
 * @param {object} [opts] — { note, force }
 */
export async function setName(projectId, alias, screenId, opts = {}) {
  const slug = normalizeAlias(alias);
  const data = await loadNames(projectId);
  const previousScreenId = data.names[slug]?.screenId || null;

  if (previousScreenId && previousScreenId !== screenId && !opts.force) {
    throw new Error(
      `Alias "${slug}" already exists (screen ${previousScreenId}). Use --force to overwrite.`
    );
  }

  data.names[slug] = {
    screenId,
    updatedAt: new Date().toISOString(),
    ...(opts.note ? { note: opts.note } : {}),
  };

  await saveNames(projectId, data);

  // Emit alias_set event
  if (!opts._skipEvent) {
    await appendEvent(projectId, {
      op: 'alias_set',
      alias: slug,
      screenId,
      ...(previousScreenId && previousScreenId !== screenId ? { previousScreenId } : {}),
      ...(opts.note ? { note: opts.note } : {}),
    });
  }

  return slug;
}

/**
 * Remove an alias.
 */
export async function removeName(projectId, alias, opts = {}) {
  const slug = normalizeAlias(alias);
  const data = await loadNames(projectId);

  if (!data.names[slug]) {
    throw new Error(`Alias "${slug}" not found in project ${projectId}.`);
  }

  const screenId = data.names[slug].screenId;
  delete data.names[slug];
  await saveNames(projectId, data);

  // Emit alias_removed event
  if (!opts._skipEvent) {
    await appendEvent(projectId, {
      op: 'alias_removed',
      alias: slug,
      screenId,
    });
  }

  return slug;
}

/**
 * Rename an alias (old → new).
 */
export async function renameName(projectId, oldAlias, newAlias, opts = {}) {
  const oldSlug = normalizeAlias(oldAlias);
  const newSlug = normalizeAlias(newAlias);
  const data = await loadNames(projectId);

  if (!data.names[oldSlug]) {
    throw new Error(`Alias "${oldSlug}" not found.`);
  }
  if (data.names[newSlug]) {
    throw new Error(`Alias "${newSlug}" already exists.`);
  }

  data.names[newSlug] = { ...data.names[oldSlug], updatedAt: new Date().toISOString() };
  delete data.names[oldSlug];
  await saveNames(projectId, data);

  // Emit alias_renamed event
  if (!opts._skipEvent) {
    await appendEvent(projectId, {
      op: 'alias_renamed',
      alias: newSlug,
      previousAlias: oldSlug,
      screenId: data.names[newSlug].screenId,
    });
  }

  return { from: oldSlug, to: newSlug };
}

/**
 * Resolve an alias to a screen ID.
 * Returns { screenId, updatedAt, note? } or null.
 */
export async function resolveName(projectId, alias) {
  const slug = normalizeAlias(alias);
  const data = await loadNames(projectId);
  return data.names[slug] || null;
}

/**
 * List all aliases for a project.
 * Returns { alias: { screenId, updatedAt, note? } }
 */
export async function listNames(projectId) {
  const data = await loadNames(projectId);
  return data.names;
}

#!/usr/bin/env node
/**
 * stitch.mjs — CLI wrapper for Google Stitch SDK
 * Uses raw MCP tool calls because the SDK wrapper classes
 * don't match the actual API response structure.
 */

import { stitch } from '@google/stitch-sdk';
import { join } from 'node:path';
import {
  RUNS_DIR, makeRunDir, downloadFile, saveLatest, loadLatest,
  saveScreenArtifacts, saveResult, resolveUrl,
} from './artifacts.mjs';
import { checkScreenshotUrl, HIRES_SUFFIX } from './download.mjs';
import { applyDesignSystem } from './design-system.mjs';
import {
  setName, removeName, renameName, resolveName, listNames, normalizeAlias, loadNames, saveNames as saveNamesRaw,
} from './names.mjs';
import {
  appendEvent, readEvents, promptPreview, makeVariantGroupId,
  historyForAlias, aliasRevisions, lineage, rebuildNames,
} from './events.mjs';

// --- Helpers ---

function die(msg) {
  console.error(`Error: ${msg}`);
  process.exit(1);
}

function ok(data) {
  console.log(JSON.stringify({ ok: true, ...data }, null, 2));
}

function parseArgs(args) {
  const flags = {};
  const positional = [];
  for (let i = 0; i < args.length; i++) {
    if (args[i].startsWith('--')) {
      const key = args[i].slice(2);
      const val = args[i + 1] && !args[i + 1].startsWith('--') ? args[++i] : true;
      flags[key] = val;
    } else {
      positional.push(args[i]);
    }
  }
  return { flags, positional };
}

// --- Argument Parsing ---

function resolveDevice(flag) {
  if (!flag) return undefined;
  const map = { desktop: 'DESKTOP', mobile: 'MOBILE', tablet: 'TABLET', agnostic: 'AGNOSTIC' };
  return map[flag.toLowerCase()] || die(`Unknown device: ${flag}`);
}

function resolveModel(flag) {
  if (!flag) return undefined;
  const map = { pro: 'GEMINI_3_1_PRO', flash: 'GEMINI_3_FLASH' };
  return map[flag.toLowerCase()] || die(`Unknown model: ${flag}`);
}

function resolveRange(flag) {
  if (!flag) return 'EXPLORE';
  const map = { refine: 'REFINE', explore: 'EXPLORE', reimagine: 'REIMAGINE' };
  return map[flag.toLowerCase()] || die(`Unknown range: ${flag}`);
}

function resolveAspects(flag) {
  if (!flag) return undefined;
  const valid = ['LAYOUT', 'COLOR_SCHEME', 'IMAGES', 'TEXT_FONT', 'TEXT_CONTENT'];
  return flag.split(',').map(a => {
    const upper = a.trim().toUpperCase();
    if (!valid.includes(upper)) die(`Unknown aspect: ${a}. Use: ${valid.join(', ')}`);
    return upper;
  });
}



async function resolveProjectId(flags) {
  if (flags.project) return flags.project;
  const latest = await loadLatest();
  if (latest?.projectId) return latest.projectId;
  die('No --project given and no latest-screen.json. Specify --project <id>.');
}

/** Extract screen ID from name like "projects/123/screens/abc" */
function extractScreenId(screen) {
  if (screen.id) return screen.id;
  if (screen.name) {
    const parts = screen.name.split('/');
    return parts[parts.length - 1];
  }
  return null;
}

async function cleanup() {
  try { await stitch.close(); } catch {}
}

/**
 * Robust tool call wrapper.
 * 
 * The Stitch MCP server uses SSE streaming. Long operations (generate, edit, variants)
 * can take 2-5 minutes. The TCP connection often drops before completion, causing
 * callTool to throw — but the server-side operation may still succeed.
 * 
 * Strategy (per SDK docs: "DO NOT RETRY, use get_screen if connection fails"):
 * 1. Call the tool
 * 2. If it succeeds → extract screen from response
 * 3. If it fails with a connection error → poll list_screens to find the new screen
 */
async function callToolRobust({ toolName, args, projectId, knownIds = null }) {
  try {
    const raw = await stitch.callTool(toolName, args);
    const screen = raw?.outputComponents?.[0]?.design?.screens?.[0];
    if (screen) return screen;
    // Response came back but no screen — try recovery
    console.error(`⚠️ No screen in response, attempting recovery via list_screens...`);
  } catch (err) {
    console.error(`⚠️ Connection error during ${toolName}: ${err.message}`);
    console.error(`   Attempting recovery via list_screens (server may still be processing)...`);
  }

  // Recovery: poll list_screens for a new screen that appeared after our call.
  // If knownIds is provided, filter to only screens that are genuinely new.
  for (let attempt = 1; attempt <= 6; attempt++) {
    const waitSec = attempt <= 3 ? 30 : 60;
    console.error(`   Recovery attempt ${attempt}/6 — waiting ${waitSec}s...`);
    await new Promise(r => setTimeout(r, waitSec * 1000));

    try {
      const listRaw = await stitch.callTool('list_screens', { projectId });
      const screens = listRaw?.screens || [];

      // Determine candidates: new screens only (when knownIds snapshot is available)
      let candidates;
      if (knownIds) {
        candidates = screens.filter(s => {
          const id = extractScreenId(s);
          return id && !knownIds.has(id);
        });
      } else {
        candidates = screens.length > 0 ? [screens[screens.length - 1]] : [];
      }

      if (candidates.length > 1) {
        console.error(`   ⚠️ Found ${candidates.length} new screens in recovery — taking the last one.`);
      }

      const candidate = candidates[candidates.length - 1];
      if (candidate) {
        const screenId = extractScreenId(candidate);
        if (screenId) {
          console.error(`   ✅ Found screen via recovery: ${screenId}`);
          const full = await stitch.callTool('get_screen', {
            projectId, screenId,
            name: `projects/${projectId}/screens/${screenId}`,
          });
          return full;
        }
      }
    } catch (pollErr) {
      console.error(`   Recovery poll failed: ${pollErr.message}`);
    }
  }

  die(`${toolName} failed and recovery could not find the screen. The operation may still be processing — check stitch.withgoogle.com.`);
}

